class UploadQuota:
    def __init__(self, monthly_limit_mib: float) -> None:
        self._limit_bytes = int(monthly_limit_mib * 1024 * 1024)
        # month -> {name: size_bytes}
        self._files: dict[str, dict[str, int]] = {}

    def _month_usage(self, month: str) -> int:
        return sum(self._files.get(month, {}).values())

    def upload(self, name: str, size_bytes: int, month: str) -> None:
        if size_bytes <= 0:
            raise ValueError("File size must be greater than zero.")

        files = self._files.setdefault(month, {})

        # If the file already exists in this month with the same name,
        # it does not count a second time.
        if name in files:
            return

        current = sum(files.values())
        if current + size_bytes > self._limit_bytes:
            raise ValueError("Upload would exceed the monthly quota.")

        files[name] = size_bytes

    def delete(self, name: str, month: str) -> None:
        files = self._files.get(month)
        if files and name in files:
            del files[name]

    def used_bytes(self, month: str) -> int:
        return self._month_usage(month)
